import { ariaAttr, boolAttr, dataAttr } from "../../dom/attrs";
import { isComposingEvent } from "../../dom/event";
import { contains } from "../../dom/query";
import { resolveDir } from "../../dom/text-dir";
import { getRovingKeyAction } from "../../focus/roving-focus";
import { isTypeaheadKey } from "../../interaction/typeahead";
import type { HTMLProps, NormalizeProps, PropTypes } from "../../machine/prop-types";
import type { Service } from "../../machine/types";
import { isFocusVisibleModality } from "../../nav";
import { parts } from "./listbox.anatomy";
import {
  getContentEl,
  getContentId,
  getItemGroupId,
  getItemGroupLabelId,
  getItemId,
  getLabelId,
  getRootId,
} from "./listbox.dom";
import type {
  ListboxApi,
  ListboxItemGroupLabelProps,
  ListboxItemGroupProps,
  ListboxItemIndicatorProps,
  ListboxItemProps,
  ListboxSchema,
} from "./listbox.types";

export function connect<T extends PropTypes>(
  service: Service<ListboxSchema>,
  normalize: NormalizeProps<T>,
): ListboxApi<T> {
  const { context, computed, prop, send, scope } = service;

  const value = context.get("value");
  const highlightedValue = context.get("highlightedValue");
  const disabled = prop("disabled");
  const orientation = prop("orientation");
  const dir = prop("dir");
  const multiple = computed("multiple");
  const itemCount = context.get("itemCount");
  const empty = itemCount === 0;
  // Read once, when the highlight landed, and held: the modality of *now* flips to
  // pointer after 300 ms of mouse movement whether or not the focus moved, and a
  // ring that blinks out under the user's hands was the result.
  const focusSource = context.get("focusSource");
  const focusVisible = focusSource !== null && isFocusVisibleModality(focusSource);

  /**
   * The single tab stop. Published by the machine, because its precedence — the
   * first *selected* row, then the memory, then the top — is a fact about DOM order
   * and `connect` has no DOM.
   *
   * The fallback covers the one pass where the machine has not read the collection
   * yet: a server render, and the client render that has to match it byte for byte.
   * A selection is the only thing knowable without the document, and a listbox that
   * has one is better entered there than not entered at all.
   */
  const tabbableValue =
    context.get("tabbableValue") ?? (itemCount === -1 ? (value[0] ?? null) : null);

  const isSelected = (item: string): boolean => value.includes(item);

  /**
   * Every key the list answers, on `content` alone: a keydown bubbles out of the
   * focused row to here, so one table serves the whole collection instead of one
   * per row.
   *
   * Ctrl and Meta are deliberately *not* dismissed wholesale the way the menu
   * dismisses them — Ctrl+A, Ctrl+Space and Ctrl+Shift+Home are all part of the
   * pattern here.
   */
  function onContentKeyDown(event: KeyboardEvent): void {
    if (isComposingEvent(event)) return;
    // APG: Tab leaves the composite, and it is the one key answered ahead of the
    // `defaultPrevented` gate — nothing here may claim it, whatever else did.
    if (event.key === "Tab") return;
    // The anti-double-play gate: an `InputSystem` that consumed this key as an
    // intent has already prevented it, and this handler stands down.
    if (event.defaultPrevented) return;

    const { key } = event;
    const mod = event.ctrlKey || event.metaKey;

    if (key === " ") {
      // Claimed here so the page cannot scroll and the typeahead cannot see it;
      // answered on keyup — the APG split `research/input.md` §1 makes a rule.
      event.preventDefault();
      return;
    }

    if (mod && (key === "a" || key === "A")) {
      // Single mode leaves it alone: "select all" of a list that holds one value is
      // not a gesture, and the browser's own select-all is worth more than a no-op.
      if (!multiple || disabled) return;
      event.preventDefault();
      send({ type: "SELECTION.ALL" });
      return;
    }

    if (key === "PageUp" || key === "PageDown") {
      event.preventDefault();
      send({
        type: "HIGHLIGHT.PAGE",
        delta: key === "PageDown" ? 1 : -1,
        extend: event.shiftKey,
      });
      return;
    }

    // The RTL mirror lives here, once, and never in a key table (architecture.md).
    // An off-axis arrow resolves to `null` and stays the browser's, so the page
    // still scrolls under a list that has not claimed that direction.
    //
    // Resolved here rather than at the `dir` hoist above: with no `dir` prop the
    // answer comes from the rendered list, and reading the DOM at the top of
    // `connect` would run on the server.
    const action = getRovingKeyAction(key, {
      orientation,
      dir: resolveDir(dir, getContentEl(scope)),
    });
    if (action !== null) {
      event.preventDefault();
      send({
        type: "HIGHLIGHT.MOVE",
        action,
        extend: event.shiftKey,
        // Ctrl/Cmd moves without choosing, which is the only way to walk a
        // single-selection list without dragging the selection along.
        quiet: mod && !event.shiftKey,
      });
      return;
    }

    if (prop("typeahead") && !mod && !event.altKey && isTypeaheadKey(key)) {
      event.preventDefault();
      send({ type: "TYPEAHEAD.KEY", key });
    }
  }

  /**
   * The other half of the Enter/Space split — and here there is no Enter at all: a
   * bare listbox has nothing to commit (that belongs to `select` and `combobox`),
   * so Enter stays the page's.
   */
  function onContentKeyUp(event: KeyboardEvent): void {
    if (event.defaultPrevented || event.key !== " " || event.altKey) return;
    event.preventDefault();
    // Shift+Space extends the range from the anchor; Ctrl+Space is the toggle's
    // documented alias, so it takes the same path as a bare Space.
    send(event.shiftKey ? { type: "SELECTION.EXTEND" } : { type: "ITEM.TOGGLE" });
  }

  function itemProps(item: ListboxItemProps): HTMLProps {
    const itemDisabled = disabled || item.disabled === true;
    const selected = isSelected(item.value);
    const highlighted = !itemDisabled && highlightedValue === item.value;

    return {
      id: getItemId(scope, item.value),
      role: "option",
      // Roving: exactly one stop in the tab order. Never `aria-activedescendant` —
      // the focus is real (règle dure), which is also what lets a gamepad drive it.
      tabIndex: item.value === tabbableValue ? 0 : -1,
      // Always present, and it carries the *selection*: the highlight is a focus and
      // announces itself by moving.
      "aria-selected": boolAttr(selected),
      // `aria-disabled`, never the native attribute: APG wants a disabled option
      // reachable, unlike a natively disabled form control (dom-collection).
      "aria-disabled": ariaAttr(itemDisabled),
      "data-value": item.value,
      "data-label": item.label,
      "data-state": selected ? "selected" : "unselected",
      "data-highlighted": dataAttr(highlighted),
      "data-disabled": dataAttr(itemDisabled),
      "data-orientation": orientation,
      // On the highlighted row only: the composite has one focus, and an attribute
      // claiming otherwise on every row describes nothing.
      "data-focus-visible": dataAttr(highlighted && focusVisible),
      "data-focus-source": highlighted ? (focusSource ?? undefined) : undefined,
      onClick(event) {
        if (event.defaultPrevented || itemDisabled) return;
        send({
          type: "ITEM.CLICK",
          value: item.value,
          shift: event.shiftKey,
          // One gesture, two spellings: Ctrl on a PC, Cmd on a Mac.
          toggle: event.ctrlKey || event.metaKey,
        });
      },
      onFocus(event) {
        if (event.defaultPrevented) return;
        send({ type: "ITEM.FOCUS", value: item.value });
      },
    };
  }

  return {
    value,
    highlightedValue,
    selectionMode: prop("selectionMode"),
    disabled,
    empty,
    isSelected,

    setValue(next: readonly string[]): void {
      send({ type: "VALUE.SET", value: next });
    },

    setHighlightedValue(next: string | null): void {
      send({ type: "HIGHLIGHT.SET", value: next });
    },

    select(next: string): void {
      send({ type: "SELECTION.SELECT", value: next });
    },

    toggle(next: string): void {
      send({ type: "ITEM.TOGGLE", value: next });
    },

    selectAll(): void {
      send({ type: "SELECTION.ALL" });
    },

    clearSelection(): void {
      send({ type: "SELECTION.CLEAR" });
    },

    getRootProps: (): T["element"] =>
      normalize.element({
        ...parts.root.attrs,
        id: getRootId(scope),
        dir,
        "data-orientation": orientation,
        "data-disabled": dataAttr(disabled),
      }),

    getLabelProps: (): T["element"] =>
      normalize.element({ ...parts.label.attrs, id: getLabelId(scope) }),

    getContentProps: (): T["element"] =>
      normalize.element({
        ...parts.content.attrs,
        id: getContentId(scope),
        role: "listbox",
        dir,
        // Only when it is true: `aria-multiselectable="false"` is the default and
        // saying it out loud on every single-selection list is noise.
        "aria-multiselectable": ariaAttr(multiple),
        // Vertical is ARIA's own implicit default for a listbox, so only the other
        // axis is worth an attribute.
        "aria-orientation": orientation === "horizontal" ? "horizontal" : undefined,
        // Never both. A rendered `label` part wins, and the prop is what names a
        // list that renders none — a dangling IDREF would name nothing at all.
        "aria-labelledby": context.get("hasLabel") ? getLabelId(scope) : undefined,
        "aria-label": context.get("hasLabel") ? undefined : prop("label"),
        "aria-disabled": ariaAttr(disabled),
        // A list with no rows has no roving stop to be reached through, so the
        // container takes one: an empty state a keyboard cannot reach is an empty
        // state nobody is told about.
        tabIndex: empty ? 0 : undefined,
        "data-empty": dataAttr(empty),
        "data-orientation": orientation,
        "data-disabled": dataAttr(disabled),
        // A spatial zone with a memory: coming back to the list lands on the row it
        // was left on. No trap and no declarative wrap — the wrap is `loopFocus`,
        // which the machine owns, and a trap would silence the engine that walks the
        // focus out of a list that has ended.
        "data-snav": "container",
        onKeyDown: onContentKeyDown,
        onKeyUp: onContentKeyUp,
        onFocusOut(event) {
          if (event.defaultPrevented) return;
          const next = event.relatedTarget as HTMLElement | null;
          // A move *within* the list is not a departure. `relatedTarget` is `null`
          // both when the focus leaves the page and when the focused row was removed
          // from under it — the second case is the collection's to answer, and
          // `syncItems` does, so all this has to get right is "still inside".
          if (contains(event.currentTarget as HTMLElement | null, next)) return;
          send({ type: "CONTENT.BLUR" });
        },
      }),

    getItemGroupProps: (group: ListboxItemGroupProps): T["element"] =>
      normalize.element({
        ...parts.itemGroup.attrs,
        id: getItemGroupId(scope, group.id),
        role: "group",
        // Declared, never assumed: written blind it is a dead IDREF *and* no
        // accessible name at once, which axe reports as `incomplete` rather than as
        // a violation — so nothing would ever catch it (the menu's lesson, kept).
        "aria-labelledby": group.label === true ? getItemGroupLabelId(scope, group.id) : undefined,
      }),

    // Not `role="presentation"`: it is what the group's `aria-labelledby` points at,
    // and a presentational node names nothing.
    getItemGroupLabelProps: (label: ListboxItemGroupLabelProps): T["element"] =>
      normalize.element({
        ...parts.itemGroupLabel.attrs,
        id: getItemGroupLabelId(scope, label.htmlFor),
      }),

    getItemProps: (item: ListboxItemProps): T["element"] =>
      normalize.element({ ...parts.item.attrs, ...itemProps(item) }),

    getItemTextProps: (): T["element"] => normalize.element({ ...parts.itemText.attrs }),

    // The checkmark. The state is `aria-selected` on the row, never this glyph — so
    // the node is hidden and the two can never disagree. The sheet shows it in touch
    // and hides it on the desktop, where the plate says the same thing — but only
    // the mark the sheet draws itself: a glyph composed into this part keeps the
    // cell in both densities.
    getItemIndicatorProps: (indicator: ListboxItemIndicatorProps): T["element"] =>
      normalize.element({
        ...parts.itemIndicator.attrs,
        "aria-hidden": ariaAttr(true),
        "data-state": isSelected(indicator.value) ? "selected" : "unselected",
      }),
  };
}

/**
 * **The item collection is read from the live DOM, never held in context.** The
 * items are composition — a filtered list rewrites them on every keystroke — and a
 * machine that had to be *told* about its own children goes out of sync the first
 * time one is rendered conditionally. The reading itself is
 * `collection/dom-collection`, shared with `menu` and `select`; what is left here
 * is this component's own selectors, its ids, and the one measurement a page
 * jump needs.
 */

import {
  getItemLabel as domItemLabel,
  findItemByValue,
  queryItems,
} from "../../collection/dom-collection";
import { contains, query } from "../../dom/query";
import { getPartId } from "../../machine/ids";
import type { Scope } from "../../machine/scope";
import type { Orientation } from "../../types";

export { getItemValue, isItemDisabled } from "../../collection/dom-collection";

const COMPONENT = "listbox";

/**
 * Written out rather than derived from `parts`: the anatomy builds the same
 * strings, and a component that imports its own anatomy into its DOM helpers pays
 * for the builder in every bundle that only wanted a query.
 */
const CONTENT_SELECTOR = '[data-part~="listbox:content"]';
export const ITEM_SELECTOR = '[data-part~="listbox:item"]';
const ITEM_TEXT_SELECTOR = '[data-part~="listbox:item-text"]';
const LABEL_SELECTOR = '[data-part~="listbox:label"]';

/** What a page jump falls back to when nothing can be measured yet. */
export const DEFAULT_PAGE_SIZE = 10;

export function getRootId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "root");
}

export function getLabelId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "label");
}

export function getContentId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "content");
}

export function getItemId(scope: Scope, value: string): string {
  return getPartId(scope, COMPONENT, "item", value);
}

export function getItemGroupId(scope: Scope, key: string): string {
  return getPartId(scope, COMPONENT, "item-group", key);
}

export function getItemGroupLabelId(scope: Scope, key: string): string {
  return getPartId(scope, COMPONENT, "item-group-label", key);
}

export function getRootEl(scope: Scope): HTMLElement | null {
  return scope.getById(getRootId(scope));
}

export function getContentEl(scope: Scope): HTMLElement | null {
  return scope.getById(getContentId(scope));
}

/** `aria-labelledby` may only point at an id that exists. */
export function hasLabel(scope: Scope): boolean {
  return query(getRootEl(scope), LABEL_SELECTOR) !== null;
}

/**
 * This listbox's own items, in DOM order. The container filter is the half a flat
 * query cannot do: a listbox inside a dialog inside a listbox nests one collection
 * in another, and the outer machine must not adopt the inner items.
 */
export function getItemEls(scope: Scope): HTMLElement[] {
  return queryItems(getContentEl(scope), ITEM_SELECTOR, CONTENT_SELECTOR);
}

export function getItemValues(scope: Scope): string[] {
  return getItemEls(scope).map((item) => item.dataset.value ?? "");
}

export function getItemEl(scope: Scope, value: string): HTMLElement | null {
  return findItemByValue(getItemEls(scope), value);
}

export function getItemLabel(item: HTMLElement): string {
  return domItemLabel(item, ITEM_TEXT_SELECTOR);
}

/** Whether the real focus is inside this listbox — never a virtual one. */
export function ownsFocus(scope: Scope): boolean {
  return contains(getContentEl(scope), scope.getActiveElement());
}

/**
 * How many rows a page jump is worth, given a viewport and a row. Pure so the
 * clamp and the fallback can be asserted without a layout: a row of zero height —
 * a list that has not been laid out yet, or one inside a collapsed container —
 * would otherwise divide into an infinity of rows.
 */
export function getPageStep(viewport: number, row: number): number {
  if (!Number.isFinite(viewport) || !Number.isFinite(row)) return DEFAULT_PAGE_SIZE;
  if (viewport <= 0 || row <= 0) return DEFAULT_PAGE_SIZE;
  return Math.max(1, Math.floor(viewport / row));
}

/**
 * Measured rather than assumed: PageDown means "a screenful", and a screenful of
 * a list is whatever the scroller can show of it. The first item stands in for
 * every row, which is what a list of equal rows makes true.
 */
export function getPageSize(scope: Scope, orientation: Orientation): number {
  const content = getContentEl(scope);
  const first = getItemEls(scope)[0];
  if (content === null || first === undefined) return DEFAULT_PAGE_SIZE;
  const rect = first.getBoundingClientRect();
  return orientation === "horizontal"
    ? getPageStep(content.clientWidth, rect.width)
    : getPageStep(content.clientHeight, rect.height);
}

/**
 * A listbox is a collection with no surface, and every decision below follows from
 * that one fact.
 *
 * **One state.** There is nothing to open, nothing to dismiss, no presence and no
 * layer — so everything lives on the machine-level `on:` and the machine-level
 * effects, the shape `radio-group` and `tabs` already have.
 *
 * **The selection is `collection/selection`, not arithmetic written again here.**
 * That module was written for this component — its `toggle()` names the gamepad X
 * button on a listbox — and it holds the one rule a file list lives by: the anchor
 * survives a range extension, so extending twice from the same anchor *replaces*
 * the range instead of growing it.
 *
 * **A range never takes a disabled row.** Every `ordered` handed to `extend` and
 * `selectAll` is the enabled collection, which is what makes "no path selects a
 * disabled item" an invariant rather than a promise.
 *
 * **The selection is not pruned when the collection shrinks.** A value whose row
 * has been filtered out of the DOM stays selected: that is the contract a filtered
 * list needs (a search that hides a chosen row has not unchosen it), and it is why
 * `value` and the DOM order are two different questions here.
 */

import { getItemValue, getNextItem, isItemDisabled } from "../../collection/dom-collection";
import {
  clearSelection as emptySelectionState,
  extend,
  type SelectionOptions,
  type SelectionState,
  select,
  selectAll,
  toggle,
} from "../../collection/selection";
import { observeChildren } from "../../dom/observers";
import { resolveDir } from "../../dom/text-dir";
import { getInitialIndex, getRemovalIndex, getRovingIntentAction } from "../../focus/roving-focus";
import { trackScrollEdges as trackEdges } from "../../interaction/scroll-edges";
import { createTypeaheadState, getByTypeahead } from "../../interaction/typeahead";
import { createMachine } from "../../machine/create-machine";
import type { Machine, MachineParams } from "../../machine/types";
import { focusElement, getInputModality, trackInputModality } from "../../nav";
import type { InputModality } from "../../types";
import {
  getContentEl,
  getItemEl,
  getItemEls,
  getItemLabel,
  getItemValues,
  getPageSize,
  hasLabel,
  ownsFocus,
} from "./listbox.dom";
import type { ListboxSchema } from "./listbox.types";

type Params = MachineParams<ListboxSchema>;

/**
 * A watch key for a list of values. Length-prefixed rather than joined on a
 * separator: `["a b"]` and `["a", "b"]` are different collections, and every
 * separator is a character a consumer is allowed to put in a `data-value`. The
 * other machines in the repo key theirs on U+0000, which cannot be written here
 * without a raw NUL in the source — and a raw NUL makes ripgrep call the file
 * binary, which hid two machines from every grep in the repo once already.
 */
function collectionKey(values: readonly string[]): string {
  let key = "";
  for (const value of values) key += `${value.length}:${value}`;
  return key;
}

function selectionOptions(params: Params): SelectionOptions {
  return {
    mode: params.computed("multiple") ? "multiple" : "single",
    deselectable: params.prop("deselectable"),
  };
}

/**
 * The same options with `deselectable` off, for the two paths that must only ever
 * *add* a selection: an arrow key under `selectOnHighlight`, and the imperative
 * `api.select()`. Moving onto the selected row and having it clear itself is a
 * toggle, and neither of those is one.
 */
function followOptions(params: Params): SelectionOptions {
  return { mode: params.computed("multiple") ? "multiple" : "single", deselectable: false };
}

function selectionState(params: Params): SelectionState {
  return { value: params.context.get("value"), anchor: params.refs.get("anchor") };
}

/** The one place the selection is written, so the anchor can never be forgotten. */
function commitSelection(params: Params, next: SelectionState): void {
  params.context.set("value", next.value);
  params.refs.set("anchor", next.anchor);
}

/** What a range and a select-all are allowed to reach: the enabled rows, in DOM order. */
function orderedEnabled(params: Params): string[] {
  return getItemEls(params.scope)
    .filter((item) => !isItemDisabled(item))
    .map(getItemValue);
}

/** The one place `highlightedValue` is written, so the modality is never forgotten. */
function commitHighlight(params: Params, value: string | null): void {
  const { context, scope } = params;
  // Read at arrival and held: the modality of *now* flips to pointer after 300ms of
  // mouse movement whether or not the focus moved, and a ring that blinks out under
  // the user's hands was the result.
  if (scope.getRootNode() !== null) {
    context.set("focusSource", value === null ? null : getInputModality(scope.getDoc()));
  }
  context.set("highlightedValue", value);
}

/**
 * The focus is real, always: roving `tabindex` and a `.focus()` on the highlighted
 * row, never `aria-activedescendant` (règle dure).
 *
 * `preventScroll: false` is the deliberate half. The library focuses without
 * scrolling everywhere else because an overlay that jumps the page on open is a
 * bug — but a listbox *is* the page, its rows are reached by arrow, and a focused
 * option left outside its own scroller is WCAG 2.4.11. So the user agent's own
 * reveal runs, and the sheet's `scroll-margin-block` decides how much of the row's
 * surroundings come with it. No manual `scrollIntoView`, and therefore no second
 * opinion about smooth versus instant.
 */
function revealAndFocus(item: HTMLElement): void {
  focusElement(item, { preventScroll: false });
}

/**
 * Where every highlight move ends: the row takes the focus, and the selection
 * follows it or does not. `extend` wins over `followFocus` — a Shift move is a
 * range, and a range is not a sequence of single selections.
 */
function applyHighlightTarget(
  params: Params,
  target: HTMLElement,
  options: { extend: boolean; quiet: boolean },
): void {
  const value = getItemValue(target);
  commitHighlight(params, value);
  revealAndFocus(target);

  if (options.extend && params.computed("multiple")) {
    commitSelection(
      params,
      extend(selectionState(params), value, orderedEnabled(params), selectionOptions(params)),
    );
    return;
  }
  if (options.quiet || !params.computed("followFocus")) return;
  commitSelection(params, select(selectionState(params), value, followOptions(params)));
}

export const machine: Machine<ListboxSchema> = createMachine<ListboxSchema>({
  props({ props }) {
    return {
      orientation: "vertical",
      selectionMode: "single",
      deselectable: false,
      // A list does not wrap. The menu does, and says so — there the collection is
      // the whole surface, here it is a region of a page a person can walk out of.
      loopFocus: false,
      typeahead: true,
      disabled: false,
      intents: null,
      ...props,
    };
  },

  context({ prop, bindable }) {
    return {
      value: bindable<readonly string[]>(() => ({
        defaultValue: prop("defaultValue") ?? [],
        value: prop("value"),
        // Order is not meaning: a selection that reported a change because the same
        // values arrived in another order would loop against a consumer that
        // normalises them.
        isEqual: (a, b) => a.length === b.length && a.every((entry) => b.includes(entry)),
        onChange: (value) => prop("onValueChange")?.({ value }),
        debugLabel: "listbox value",
      })),
      highlightedValue: bindable<string | null>(() => ({
        defaultValue: prop("defaultHighlightedValue") ?? null,
        value: prop("highlightedValue"),
        onChange: (value) => prop("onHighlightChange")?.({ value }),
        debugLabel: "listbox highlightedValue",
      })),
      focusSource: bindable<InputModality | null>(() => ({ defaultValue: null })),
      // `-1` is "not measured yet", and it is not the same fact as "empty": a server
      // render that answered 0 would promise a tab stop and an empty state the
      // client takes back on its first sync.
      itemCount: bindable<number>(() => ({ defaultValue: -1 })),
      hasLabel: bindable<boolean>(() => ({ defaultValue: false })),
      tabbableValue: bindable<string | null>(() => ({ defaultValue: null })),
    };
  },

  refs() {
    return { anchor: null, typeahead: createTypeaheadState(), orderedValues: [] };
  },

  computed: {
    multiple: ({ prop }) => prop("selectionMode") === "multiple",
    // The native `<select>` model in single mode, off in multiple — where an arrow
    // that selected as it moved would make a range impossible to build.
    followFocus: ({ prop }) => prop("selectOnHighlight") ?? prop("selectionMode") !== "multiple",
  },

  initialState() {
    return "idle";
  },

  effects: ["trackModality", "trackItems", "trackScrollEdges", "captureIntents"],

  watch({ context, scope, track, action }) {
    // The tab stop rides on the selection, which no child mutation announces — so
    // the collection is a dependency like any other and the observer below is left
    // to cover the mutations no render caused.
    //
    // Keyed through `collectionKey` rather than a join: two different lists must
    // never produce the same string, and no separator character is safe in a
    // `data-value` a consumer chose.
    track(
      () => [
        collectionKey(context.get("value")),
        context.get("highlightedValue"),
        collectionKey(getItemValues(scope)),
      ],
      () => action(["syncItems"]),
    );
  },

  on: {
    // **The focus is moved last, and the order is a contract.** `focusElement`
    // dispatches synchronously, the row's own handler answers it with `ITEM.FOCUS`,
    // and the interpreter delivers that re-entrantly — so `event` is the focus by
    // the time anything after it runs. An action that still had to read the click
    // would find one that was never sent.
    "ITEM.CLICK": {
      guard: "isItemEnabled",
      actions: ["highlightItem", "applyClick", "focusHighlighted"],
    },
    "ITEM.FOCUS": { actions: ["adoptFocus"] },
    "CONTENT.BLUR": { actions: ["clearFocusSource"] },
    "HIGHLIGHT.MOVE": { guard: "isInteractive", actions: ["moveHighlight"] },
    "HIGHLIGHT.PAGE": { guard: "isInteractive", actions: ["pageHighlight"] },
    "HIGHLIGHT.SET": { actions: ["setHighlight"] },
    "ITEM.TOGGLE": { guard: "isInteractive", actions: ["toggleItem"] },
    "SELECTION.SELECT": { guard: "isInteractive", actions: ["selectItem"] },
    "SELECTION.EXTEND": { guard: "isInteractive", actions: ["extendToItem"] },
    "SELECTION.ALL": { guard: "isMultiple", actions: ["selectAllItems"] },
    "SELECTION.CLEAR": { actions: ["clearSelection"] },
    "VALUE.SET": { actions: ["setValue"] },
    "TYPEAHEAD.KEY": { guard: "isTypeaheadEnabled", actions: ["typeaheadHighlight"] },
    "ITEMS.SYNC": { actions: ["syncItems"] },
  },

  states: {
    idle: {},
  },

  implementations: {
    guards: {
      isInteractive: ({ prop }) => !prop("disabled"),
      // Interactivity folded in: a transition takes one guard, and select-all is
      // meaningless in single mode — "all" is not a value a radio-shaped list has.
      isMultiple: ({ prop, computed }) => !prop("disabled") && computed("multiple"),
      isItemEnabled({ prop, event, scope }) {
        if (prop("disabled") || event.type !== "ITEM.CLICK") return false;
        const item = getItemEl(scope, event.value);
        return item !== null && !isItemDisabled(item);
      },
      isTypeaheadEnabled: ({ prop }) => prop("typeahead") && !prop("disabled"),
    },

    actions: {
      highlightItem(params) {
        if (params.event.type === "ITEM.CLICK") commitHighlight(params, params.event.value);
      },

      /**
       * A real focus arriving from outside — a Tab, a spatial move, a click that
       * landed on a row. It moves the highlight and nothing else: even under
       * `selectOnHighlight`, entering a list does not choose from it. Only an arrow
       * does that.
       */
      adoptFocus(params) {
        const { event, scope } = params;
        if (event.type !== "ITEM.FOCUS") return;
        // A disabled row stays focusable — `aria-disabled`, never `disabled` — so a
        // pointer can still land on one. The highlight is what the arrows measure
        // from, and it must not come to rest on a row they step over.
        const item = getItemEl(scope, event.value);
        if (item !== null && isItemDisabled(item)) return;
        commitHighlight(params, event.value);
      },

      /**
       * The highlight is deliberately kept: it is the memory the tab stop comes back
       * to, and the same row the spatial zone's `last` entry strategy points at.
       */
      clearFocusSource({ context }) {
        context.set("focusSource", null);
      },

      moveHighlight(params) {
        const { context, event, prop, scope } = params;
        if (event.type !== "HIGHLIGHT.MOVE") return;
        const current = context.get("highlightedValue");
        const target = getNextItem(getItemEls(scope), current, event.action, prop("loopFocus"));
        // `null` is an empty collection; an unchanged value is the end of the list.
        // The keyboard holds a list at its ends — the connect has already stopped
        // the page from scrolling instead — while the d-pad hands the move back to
        // the spatial engine (see `captureIntents`).
        if (target === null || getItemValue(target) === current) return;
        applyHighlightTarget(params, target, {
          extend: event.extend === true,
          quiet: event.quiet === true,
        });
      },

      pageHighlight(params) {
        const { context, event, prop, scope } = params;
        if (event.type !== "HIGHLIGHT.PAGE") return;
        const items = getItemEls(scope);
        const action = event.delta === 1 ? "next" : "prev";
        // A screenful minus one row: the overlap every paging list keeps, so the
        // reader has a line in common between the view they left and the one they
        // arrive at.
        const step = Math.max(1, getPageSize(scope, prop("orientation")) - 1);

        let current = context.get("highlightedValue");
        let target: HTMLElement | null = null;
        for (let count = 0; count < step; count++) {
          // Never looping, whatever `loopFocus` says: a page jump that wrapped would
          // answer "move by a screenful" with "jump to the other end".
          const next = getNextItem(items, current, action, false);
          if (next === null) break;
          const value = getItemValue(next);
          if (value === current) break;
          current = value;
          target = next;
        }
        if (target === null) return;
        applyHighlightTarget(params, target, { extend: event.extend === true, quiet: false });
      },

      setHighlight(params) {
        if (params.event.type === "HIGHLIGHT.SET") commitHighlight(params, params.event.value);
      },

      focusHighlighted({ context, scope }) {
        const value = context.get("highlightedValue");
        if (value === null) return;
        const item = getItemEl(scope, value);
        // Explicit, and not a formality: WebKit does not focus a `div` under a
        // click, so the roving tab stop and the real focus would part company on the
        // first pointer selection.
        if (item !== null) revealAndFocus(item);
      },

      applyClick(params) {
        const { computed, event, prop } = params;
        if (event.type !== "ITEM.CLICK") return;
        const options = selectionOptions(params);
        const state = selectionState(params);

        if (computed("multiple") && event.shift) {
          commitSelection(params, extend(state, event.value, orderedEnabled(params), options));
        } else if (computed("multiple") && event.toggle) {
          commitSelection(params, toggle(state, event.value, options));
        } else {
          // Replaces in both modes: `select` in multiple mode is the plain click of
          // every file list, the one that drops everything else.
          commitSelection(params, select(state, event.value, options));
        }
        prop("onSelect")?.({ value: event.value });
      },

      selectItem(params) {
        const { event, prop } = params;
        if (event.type !== "SELECTION.SELECT") return;
        commitSelection(params, select(selectionState(params), event.value, followOptions(params)));
        prop("onSelect")?.({ value: event.value });
      },

      toggleItem(params) {
        const { context, event, prop, scope } = params;
        if (event.type !== "ITEM.TOGGLE") return;
        const target = event.value ?? context.get("highlightedValue");
        if (target === null) return;
        // A value with no row is allowed through: the selection outlives a filter,
        // so unselecting something the search has hidden has to keep working. A row
        // that *is* rendered and disabled is refused.
        const item = getItemEl(scope, target);
        if (item !== null && isItemDisabled(item)) return;
        commitSelection(params, toggle(selectionState(params), target, selectionOptions(params)));
        prop("onSelect")?.({ value: target });
      },

      extendToItem(params) {
        const { context, event, prop, scope } = params;
        if (event.type !== "SELECTION.EXTEND") return;
        const target = event.value ?? context.get("highlightedValue");
        if (target === null) return;
        const item = getItemEl(scope, target);
        if (item !== null && isItemDisabled(item)) return;
        // With no anchor `extend` falls back to a plain select, which is already
        // written and already right: the first half of a range is a selection.
        commitSelection(
          params,
          extend(selectionState(params), target, orderedEnabled(params), selectionOptions(params)),
        );
        prop("onSelect")?.({ value: target });
      },

      selectAllItems(params) {
        commitSelection(
          params,
          selectAll(selectionState(params), orderedEnabled(params), selectionOptions(params)),
        );
      },

      clearSelection(params) {
        commitSelection(params, emptySelectionState());
      },

      setValue(params) {
        const { event } = params;
        if (event.type !== "VALUE.SET") return;
        // The anchor follows the last value written, exactly as `toggle` leaves it:
        // a range extended straight after a programmatic write has to measure from
        // somewhere a consumer can predict.
        commitSelection(params, { value: event.value, anchor: event.value.at(-1) ?? null });
      },

      typeaheadHighlight(params) {
        const { context, event, refs, scope } = params;
        if (event.type !== "TYPEAHEAD.KEY") return;
        const items = getItemEls(scope);
        const current = context.get("highlightedValue");
        const match = getByTypeahead(refs.get("typeahead"), event.key, {
          items,
          itemToString: getItemLabel,
          isItemDisabled,
          activeIndex: items.findIndex((item) => getItemValue(item) === current),
        });
        if (match === null) return;
        // Never a range: typing a letter is a jump, and a jump that grew a selection
        // would make the keyboard the one input that cannot browse a list.
        applyHighlightTarget(params, match, { extend: false, quiet: false });
      },

      /**
       * Everything the machine knows about its own collection, re-read in one place.
       *
       * The focus rescue is the half that matters (parity with the reference app's filtered
       * palettes): a list that re-renders under a filter takes the highlighted row
       * away with it, and the browser drops the focus on `<body>`. APG says where it
       * goes — the next enabled row, the previous one when there is no next — and
       * the index it counts from is the one the row *had*, read from the snapshot
       * this action leaves behind on every pass.
       */
      syncItems(params) {
        const { context, refs, scope } = params;
        // "I cannot see the items" is not "there are no items": a server render and
        // the first client pass both land here before anything exists, and settling
        // on that would publish an empty state nobody is in.
        if (getContentEl(scope) === null) return;

        const items = getItemEls(scope);
        const values = items.map(getItemValue);
        const isDisabled = (index: number): boolean => {
          const item = items[index];
          return item !== undefined && isItemDisabled(item);
        };

        context.set("itemCount", values.length);
        context.set("hasLabel", hasLabel(scope));

        const previous = refs.get("orderedValues");
        let highlighted = context.get("highlightedValue");
        if (
          highlighted !== null &&
          !values.includes(highlighted) &&
          previous.includes(highlighted)
        ) {
          const from = Math.min(previous.indexOf(highlighted), values.length - 1);
          const rescued =
            values.length === 0
              ? -1
              : isDisabled(from)
                ? getRemovalIndex(from, { count: values.length, isDisabled })
                : from;
          highlighted = rescued === -1 ? null : (values[rescued] ?? null);
          commitHighlight(params, highlighted);

          // Only when the focus really fell out of the document's control. Reading
          // `activeElement` rather than a flag is what makes this engine-independent:
          // removing a focused node fires `blur` in some engines and silently moves
          // the focus to `<body>` in others, so the attribute this could have keyed
          // on is not reliably there.
          const active = scope.getActiveElement();
          const lost =
            active === null || active === scope.getDoc().body || active === getContentEl(scope);
          if (lost && highlighted !== null) {
            const item = getItemEl(scope, highlighted);
            if (item !== null) revealAndFocus(item);
          }
        }

        // The single tab stop, and its precedence is APG's: focus enters a listbox at
        // the selected option, then at wherever it was left, then at the top.
        const value = context.get("value");
        let stop: string | null = null;
        for (let index = 0; index < values.length; index++) {
          const candidate = values[index];
          if (candidate === undefined || isDisabled(index)) continue;
          if (value.includes(candidate)) {
            stop = candidate;
            break;
          }
        }
        if (stop === null && highlighted !== null) {
          const index = values.indexOf(highlighted);
          if (index !== -1 && !isDisabled(index)) stop = highlighted;
        }
        if (stop === null) {
          const first = getInitialIndex({ count: values.length, isDisabled });
          stop = first === -1 ? null : (values[first] ?? null);
        }
        context.set("tabbableValue", stop);

        refs.set("orderedValues", values);
      },
    },

    effects: {
      // No listener: the source is read once, when the focus lands. Holding the
      // handle is the whole job — the tracker has to be running before the first Tab.
      trackModality({ scope }) {
        if (scope.getRootNode() === null) return;
        return trackInputModality(scope.getDoc());
      },

      trackItems({ scope, send }) {
        send({ type: "ITEMS.SYNC" });
        // Rows appear and disappear with the app's own state — a filter above the
        // list is the whole reason this component exists in the reference app — and the machine
        // has to survive that without the consumer telling anyone.
        return observeChildren(getContentEl(scope), () => send({ type: "ITEMS.SYNC" }));
      },

      /**
       * A list in a page can be capped by whatever holds it, with no scrollbar to
       * say so: native desktop overlay scrollbars hide until the pointer moves, and a finger
       * gets none at all. Never conditioned on `prefers-reduced-motion` — this is not
       * an animation, it is the only indication that there is more list.
       */
      trackScrollEdges({ scope }) {
        return trackEdges(getContentEl(scope));
      },

      /**
       * Neither `trapped` nor `base`. A trapping scope answers `consumed` to
       * everything it declines and silences every non-`base` scope under it
       * outside its surface; a list is not a surface, and the spatial engine, a
       * `base` scope, would move the focus out of it anyway.
       *
       * `back` (B) is deliberately not claimed: a listbox is not a layer, and one
       * that swallowed B would make a dialog containing a list impossible to leave.
       * Neither is `contextMenu` (Y), which is the gesture that opens a context menu
       * on the focused row, nor `select` (A) — the input system clicks the focused
       * element for that, so a pad activation runs exactly the handlers a click does.
       * One path in, never two.
       */
      captureIntents({ prop, computed, context, scope, send }) {
        const host = prop("intents");
        if (host === null || host === undefined) return;

        return host.pushScope(
          (event) => {
            if (prop("disabled") || !ownsFocus(scope)) return false;

            if (event.intent === "secondary") {
              // X toggles the highlighted row without moving it (CDC §4.4). In single
              // mode it is left free for whoever else wants it.
              if (!computed("multiple")) return false;
              send({ type: "ITEM.TOGGLE" });
              return true;
            }

            if (event.intent === "pageUp" || event.intent === "pageDown") {
              send({ type: "HIGHLIGHT.PAGE", delta: event.intent === "pageDown" ? 1 : -1 });
              return true;
            }

            // The mirror lives in `roving-focus`, once, and is entered from here by
            // the intent rather than by the key it is the twin of: the intents are
            // physical by contract, and an off-axis one resolves to `null` so a
            // sideways press walks out of the list instead of being swallowed.
            const action = getRovingIntentAction(event.intent, {
              orientation: prop("orientation"),
              dir: resolveDir(prop("dir"), getContentEl(scope)),
            });
            if (action === null) return false;

            if (action === "next" || action === "prev") {
              const current = context.get("highlightedValue");
              const target = getNextItem(getItemEls(scope), current, action, prop("loopFocus"));
              // **Declined at the end of the list, and that is the rule that keeps a
              // d-pad out of a trap.** The intent falls through to the spatial engine,
              // which walks the focus out of the zone geometrically. The keyboard holds
              // the stop instead, because its fallback is the page scrolling, not a
              // navigation engine.
              if (target === null || getItemValue(target) === current) return false;
            }

            send({ type: "HIGHLIGHT.MOVE", action });
            return true;
          },
          { within: () => getContentEl(scope) },
        );
      },
    },
  },
});

import type { RovingAction } from "../../focus/roving-focus";
import type { TypeaheadState } from "../../interaction/typeahead";
import type { PropTypes } from "../../machine/prop-types";
import type { MachineSchema } from "../../machine/types";
import type { IntentScopeHost } from "../../nav";
import type { Direction, InputModality, Orientation } from "../../types";

export type ListboxSelectionMode = "single" | "multiple";

export interface ListboxValueChangeDetails {
  readonly value: readonly string[];
}

export interface ListboxHighlightChangeDetails {
  readonly value: string | null;
}

export interface ListboxSelectDetails {
  readonly value: string;
}

export interface ListboxMachineProps {
  /** Not defaulted, deliberately: left unset the resolved page direction governs, so a subtree inside an RTL region inherits instead of being reset to `ltr`. */
  readonly dir?: Direction | undefined;
  readonly orientation?: Orientation | undefined;
  readonly selectionMode?: ListboxSelectionMode | undefined;
  /** Single mode: re-selecting the selected item clears it. Off by default. */
  readonly deselectable?: boolean | undefined;
  /**
   * The selection follows the focus, which is the native `<select>` model.
   * Resolved default: on in single mode, off in multiple. An extend or a quiet
   * move overrides it for that move alone.
   */
  readonly selectOnHighlight?: boolean | undefined;
  /** Off by default: a list does not wrap. A menu does, and says so. */
  readonly loopFocus?: boolean | undefined;
  readonly typeahead?: boolean | undefined;
  readonly disabled?: boolean | undefined;
  /** The accessible name when no `label` part is rendered. */
  readonly label?: string | undefined;
  readonly intents?: IntentScopeHost | null | undefined;

  readonly value?: readonly string[] | undefined;
  readonly defaultValue?: readonly string[] | undefined;
  readonly highlightedValue?: string | null | undefined;
  readonly defaultHighlightedValue?: string | null | undefined;

  readonly onValueChange?: ((details: ListboxValueChangeDetails) => void) | undefined;
  readonly onHighlightChange?: ((details: ListboxHighlightChangeDetails) => void) | undefined;
  /**
   * Every user act of selection aimed at an item — a click, Space, the pad's A or
   * X — whether or not the value ends up different.
   */
  readonly onSelect?: ((details: ListboxSelectDetails) => void) | undefined;
}

export interface ResolvedListboxMachineProps extends ListboxMachineProps {
  readonly orientation: Orientation;
  readonly selectionMode: ListboxSelectionMode;
  readonly deselectable: boolean;
  readonly loopFocus: boolean;
  readonly typeahead: boolean;
  readonly disabled: boolean;
  readonly intents: IntentScopeHost | null;
}

export interface ListboxItemProps {
  readonly value: string;
  readonly disabled?: boolean | undefined;
  /** Feeds the typeahead and `data-label` — the sheet reserves a width from it. */
  readonly label?: string | undefined;
}

export interface ListboxItemGroupProps {
  readonly id: string;
  /**
   * **A flag, not the text.** Say it when the group renders an
   * `itemGroupLabel`; left out, no `aria-labelledby` is written at all, because a
   * dangling IDREF names nothing and axe only ever grades it `incomplete`.
   */
  readonly label?: boolean | undefined;
}

export interface ListboxItemGroupLabelProps {
  readonly htmlFor: string;
}

export interface ListboxItemIndicatorProps {
  readonly value: string;
}

export interface ListboxSchema extends MachineSchema {
  state: "idle";
  props: ResolvedListboxMachineProps;
  context: {
    value: readonly string[];
    highlightedValue: string | null;
    focusSource: InputModality | null;
    /** `-1` until the collection has been read — see `syncItems`. */
    itemCount: number;
    hasLabel: boolean;
    /** The single tab stop, published as a value: DOM order decides it. */
    tabbableValue: string | null;
  };
  refs: {
    /** Where a range extension measures from. No render depends on it. */
    anchor: string | null;
    typeahead: TypeaheadState;
    /** The collection as of the last sync — the focus rescue reads it. */
    orderedValues: readonly string[];
  };
  computed: {
    multiple: boolean;
    followFocus: boolean;
  };
  event:
    | { type: "ITEM.CLICK"; value: string; shift: boolean; toggle: boolean }
    | { type: "ITEM.FOCUS"; value: string }
    | { type: "CONTENT.BLUR" }
    | { type: "HIGHLIGHT.MOVE"; action: RovingAction; extend?: boolean; quiet?: boolean }
    | { type: "HIGHLIGHT.PAGE"; delta: -1 | 1; extend?: boolean }
    | { type: "HIGHLIGHT.SET"; value: string | null }
    | { type: "ITEM.TOGGLE"; value?: string }
    | { type: "SELECTION.SELECT"; value: string }
    | { type: "SELECTION.EXTEND"; value?: string }
    | { type: "SELECTION.ALL" }
    | { type: "SELECTION.CLEAR" }
    | { type: "VALUE.SET"; value: readonly string[] }
    | { type: "TYPEAHEAD.KEY"; key: string }
    | { type: "ITEMS.SYNC" };
  action:
    | "highlightItem"
    | "adoptFocus"
    | "clearFocusSource"
    | "moveHighlight"
    | "pageHighlight"
    | "setHighlight"
    | "focusHighlighted"
    | "applyClick"
    | "selectItem"
    | "toggleItem"
    | "extendToItem"
    | "selectAllItems"
    | "clearSelection"
    | "setValue"
    | "typeaheadHighlight"
    | "syncItems";
  guard: "isInteractive" | "isMultiple" | "isItemEnabled" | "isTypeaheadEnabled";
  effect: "trackModality" | "trackItems" | "trackScrollEdges" | "captureIntents";
}

export interface ListboxApi<T extends PropTypes = PropTypes> {
  readonly value: readonly string[];
  readonly highlightedValue: string | null;
  readonly selectionMode: ListboxSelectionMode;
  readonly disabled: boolean;
  readonly empty: boolean;
  setValue(value: readonly string[]): void;
  setHighlightedValue(value: string | null): void;
  /** Replaces the selection, in both modes. */
  select(value: string): void;
  /** Ctrl/Cmd-click, and the pad's X button. */
  toggle(value: string): void;
  /** A no-op in single mode, where "all" is not a selection. */
  selectAll(): void;
  clearSelection(): void;
  isSelected(value: string): boolean;

  getRootProps(): T["element"];
  getLabelProps(): T["element"];
  getContentProps(): T["element"];
  getItemGroupProps(props: ListboxItemGroupProps): T["element"];
  getItemGroupLabelProps(props: ListboxItemGroupLabelProps): T["element"];
  getItemProps(props: ListboxItemProps): T["element"];
  getItemTextProps(): T["element"];
  getItemIndicatorProps(props: ListboxItemIndicatorProps): T["element"];
}

/**
 * `<Listbox options={…}/>` — `select`'s collection without `select`'s surface:
 * the same entry grammar, the same group translation, and no trigger, no portal,
 * no positioner, because a listbox is already on the page.
 *
 * **`options` and not `items`**, which is the closed vocabulary's own distinction
 * and not a coin toss: `options` is what a *value* is chosen from — `select`,
 * `radio-group`, `checkbox-group` — and `items` is what a surface *contains*,
 * whether or not anything is selected — `menu`, `tabs`, `toolbar`. A listbox
 * publishes `value`/`onValueChange`, so it is the first family.
 *
 * **A group's `id` is required, and `label` on the part is a boolean.**
 * `ListboxItemGroupProps.label` does not carry the text: it says "this group
 * renders a label part", and the machine points an `aria-labelledby` at an id
 * derived from the group's key. So the layer has to render `ListboxItemGroupLabel`
 * *and* pin the key — written blind, the attribute is a dead IDREF and the group
 * is nameless at the same time, which axe grades `incomplete` rather than a
 * violation and therefore nothing reports. That is why `ComposedGroup` requires
 * `id` where the part defaults it from a `useId`.
 *
 * **The indicator is placed on every row and rendered empty**, which this wave
 * made possible: `_listbox.scss` now draws the checkmark under `:where(:empty)`,
 * two borders in the shape `_menu.scss` already uses. Before that the sheet held a
 * cell the consumer had to fill, and the composed layer had no way to fill it
 * without a slot outside the closed vocabulary. `renderOption` and
 * `parts.itemIndicator` both still take a consumer's own SVG, and the `:empty`
 * guard steps aside for either.
 *
 * **`ListboxItem.label` is not the drawn text.** The drawn text is
 * `ListboxItemText`; `label` is what the typeahead matches on, and it has to be a
 * plain string for that. So an entry's `label` is spent twice when it is a string
 * and only once when it is not — which is why the entry's own `label` is typed
 * `string` here rather than `ReactNode`, and richer rows go through
 * `renderOption`.
 *
 * **The root's `label` is consumed, not forwarded**, and it is the one machine
 * prop this layer does not pass straight through. `ListboxMachineProps.label` is
 * documented as "the accessible name when no `label` part is rendered" — it lands
 * as an `aria-label` on the root. This layer *does* render the part when given a
 * label, so forwarding it too would name the list twice: an `aria-label` on the
 * root, which wins, and a visible `ListboxLabel` underneath it that a screen
 * reader never reaches. Given none, neither is emitted and the part is not
 * rendered, because an empty label names nothing. A consumer who wants the
 * `aria-label` without visible text reaches for the parts.
 */

import type { ReactNode } from "react";
import type { ComposedDecoration, ComposedGroup } from "../../composed";
import type { PartProps } from "../../create-part";
import {
  ListboxContent,
  ListboxItem,
  ListboxItemGroup,
  ListboxItemGroupLabel,
  ListboxItemIndicator,
  ListboxItemText,
  ListboxLabel,
  ListboxRoot,
  type UseListboxProps,
} from "./listbox";

/** One row. */
export interface ListboxOption<Meta = never> extends ComposedDecoration<Meta> {
  readonly value: string;
  /** Drawn, and what the typeahead matches on — hence `string` and not `ReactNode`. */
  readonly label: string;
  readonly disabled?: boolean | undefined;
}

export type ListboxEntry<Meta = never> = ListboxOption<Meta> | ComposedGroup<ListboxOption<Meta>>;

/**
 * The escape hatch, applied **last** on every part: what the layer defaults is a
 * default, and the consumer's entry wins over it.
 */
type Row<Element extends keyof React.JSX.IntrinsicElements> = Omit<
  PartProps<Element>,
  "id" | "ref" | "aria-labelledby" | "aria-describedby"
>;

export interface ListboxParts {
  readonly label?: PartProps<"span"> | undefined;
  readonly content?: PartProps<"div"> | undefined;
  /** Applied to EVERY group, hence no `id` — the entry's own field. */
  readonly itemGroup?: Row<"div"> | undefined;
  readonly itemGroupLabel?: Row<"span"> | undefined;
  /** Applied to EVERY row, hence no `value`, `label` or `disabled`. */
  readonly item?: Row<"div"> | undefined;
  readonly itemText?: Row<"span"> | undefined;
  readonly itemIndicator?: Row<"span"> | undefined;
}

export interface ListboxComposedProps<Meta = never>
  extends UseListboxProps,
    Omit<PartProps<"div", UseListboxProps>, "children"> {
  readonly options: readonly ListboxEntry<Meta>[];
  /**
   * Replaces a row's contents, and is handed what the layer would have rendered so
   * a consumer can wrap rather than restate. The row itself — its `value`, its
   * selection, its tab stop — stays the layer's.
   */
  readonly renderOption?:
    | ((option: ListboxOption<Meta>, defaults: ReactNode) => ReactNode)
    | undefined;
  readonly parts?: ListboxParts | undefined;
}

export function Listbox<Meta = never>(props: ListboxComposedProps<Meta>): ReactNode {
  const { options, label, renderOption, parts, ...root } = props;

  const row = (option: ListboxOption<Meta>): ReactNode => {
    const defaults = (
      <>
        {option.icon}
        <ListboxItemText {...parts?.itemText}>{option.label}</ListboxItemText>
        <ListboxItemIndicator {...parts?.itemIndicator} />
      </>
    );

    return (
      <ListboxItem
        key={option.value}
        value={option.value}
        label={option.label}
        disabled={option.disabled}
        {...parts?.item}
      >
        {renderOption === undefined ? defaults : renderOption(option, defaults)}
      </ListboxItem>
    );
  };

  return (
    <ListboxRoot {...root}>
      {label == null ? null : <ListboxLabel {...parts?.label}>{label}</ListboxLabel>}
      <ListboxContent {...parts?.content}>
        {options.map((entry) =>
          "options" in entry ? (
            <ListboxItemGroup key={entry.id} id={entry.id} label {...parts?.itemGroup}>
              <ListboxItemGroupLabel {...parts?.itemGroupLabel}>
                {entry.label}
              </ListboxItemGroupLabel>
              {entry.options.map(row)}
            </ListboxItemGroup>
          ) : (
            row(entry)
          ),
        )}
      </ListboxContent>
    </ListboxRoot>
  );
}

/**
 * The listbox in React: one machine in the root, and nothing else to arrange.
 *
 * There is no portal, no presence and no layer here — a listbox is content in the
 * page — so what the adapter owes the machine is exactly two things a consumer
 * should never wire by hand: the intent scope a d-pad arrives on, taken from the
 * nearest `<NavProvider>`, and the two scroll-edge bands the surface owes
 * itself.
 *
 * **The items are composition, never an `items` prop.** The machine reads the live
 * DOM, so a row only has to publish its own value on its own parts — which is what
 * makes a filtered list work without a registry anybody has to keep in step.
 */

import type { Service } from "@standarui/core";
import * as listbox from "@standarui/core/listbox";
import { type ReactNode, useId } from "react";
import { createPart, type PartProps } from "../../create-part";
import { useIntentScopeHost } from "../../nav";
import { normalizeProps, type ReactPropTypes } from "../../normalize-props";
import { createPartContext } from "../../part-context";
import { splitProps } from "../../split-props";
import { type MachineRuntimeProps, useMachine } from "../../use-machine";
import { useRender } from "../../use-render";

export type ListboxApi = listbox.ListboxApi<ReactPropTypes>;

export interface UseListboxProps extends listbox.ListboxMachineProps, MachineRuntimeProps {}

const ListboxContext = createPartContext<ListboxApi>("Listbox");
/** A row publishes its identity so its own parts do not have to repeat it. */
const ListboxItemContext = createPartContext<string>("Listbox");
const ListboxGroupContext = createPartContext<string>("Listbox");

function useListboxService(props: UseListboxProps): Service<listbox.ListboxSchema> {
  const host = useIntentScopeHost();

  return useMachine(listbox.machine, {
    ...props,
    // `??` would override an explicit `null`, and `null` is how a consumer says
    // "this list answers no gamepad" while a provider is mounted above it.
    intents: props.intents === undefined ? host : props.intents,
  });
}

/** The machine on its own, for a consumer who would rather write the markup. */
export function useListbox(props: UseListboxProps): ListboxApi {
  return listbox.connect(useListboxService(props), normalizeProps);
}

/** The api of the list a subtree sits in — a consumer's own chrome reads it. */
export function useListboxContext(): ListboxApi {
  return ListboxContext.usePart("ListboxContext");
}

const MACHINE_PROPS = [
  "id",
  "ids",
  "getRootNode",
  "dir",
  "orientation",
  "selectionMode",
  "deselectable",
  "selectOnHighlight",
  "loopFocus",
  "typeahead",
  "disabled",
  "label",
  "intents",
  "value",
  "defaultValue",
  "highlightedValue",
  "defaultHighlightedValue",
  "onValueChange",
  "onHighlightChange",
  "onSelect",
] as const;

export interface ListboxRootProps extends UseListboxProps, PartProps<"div", UseListboxProps> {}

export function ListboxRoot(props: ListboxRootProps): ReactNode {
  const [machineProps, rest] = splitProps(props, MACHINE_PROPS);
  const { render, asChild, children, ...elementProps } = rest;
  const api = useListbox(machineProps);

  return (
    <ListboxContext.Provider value={api}>
      {useRender({
        render,
        asChild,
        element: "div",
        props: api.getRootProps(),
        elementProps,
        children,
      })}
    </ListboxContext.Provider>
  );
}

/**
 * The name of the list. Rendering it is what switches the content from
 * `aria-label` to `aria-labelledby` — the machine sees the part in the DOM, so the
 * two can never disagree and the IDREF can never dangle.
 */
export const ListboxLabel: (props: PartProps<"span">) => ReactNode = createPart(ListboxContext, {
  name: "ListboxLabel",
  element: "span",
  props: (api) => api.getLabelProps(),
});

/**
 * The scroll affordance, and the reason it is two nodes the adapter writes rather
 * than a part or a pseudo-element: nothing composes into them and nothing renders
 * inside them, so they are decoration the list owes itself. They must be the
 * outermost children on both sides — the first row is what slides under the top
 * band.
 */
const SCROLL_EDGES = {
  up: <div data-scroll-edge="up" aria-hidden="true" />,
  down: <div data-scroll-edge="down" aria-hidden="true" />,
};

export function ListboxContent(props: PartProps<"div">): ReactNode {
  const { render, asChild, children, ...elementProps } = props;
  const api = ListboxContext.usePart("ListboxContent");

  return useRender({
    render,
    asChild,
    element: "div",
    props: api.getContentProps(),
    elementProps,
    children: (
      <>
        {SCROLL_EDGES.up}
        {children}
        {SCROLL_EDGES.down}
      </>
    ),
  });
}

export interface ListboxItemGroupProps extends PartProps<"div", listbox.ListboxItemGroupProps> {
  /** Any stable key of the consumer's; a `useId()` when they have none. */
  readonly id?: string | undefined;
  /**
   * **A flag, not the text.** Say `label` when the group renders a
   * `ListboxItemGroupLabel`. Left out, the group carries no reference at all —
   * written blind the attribute points at an element nobody rendered, and a group
   * with a dead IDREF has no accessible name *and* nothing to report it, since axe
   * grades that `incomplete` rather than a violation.
   */
  readonly label?: boolean | undefined;
}

export function ListboxItemGroup(props: ListboxItemGroupProps): ReactNode {
  const [group, rest] = splitProps(props, ["id", "label"]);
  const { render, asChild, children, ...elementProps } = rest;
  const api = ListboxContext.usePart("ListboxItemGroup");
  const fallback = useId();
  // Published so the label does not have to repeat it — both ids are derived from
  // the same key, which is the whole of `aria-labelledby` here.
  const key = group.id ?? fallback;

  return (
    <ListboxGroupContext.Provider value={key}>
      {useRender({
        render,
        asChild,
        element: "div",
        props: api.getItemGroupProps({ id: key, label: group.label }),
        elementProps,
        children,
      })}
    </ListboxGroupContext.Provider>
  );
}

export function ListboxItemGroupLabel(props: PartProps<"span">): ReactNode {
  const { render, asChild, children, ...elementProps } = props;
  const api = ListboxContext.usePart("ListboxItemGroupLabel");
  const htmlFor = ListboxGroupContext.usePart("ListboxItemGroupLabel");

  return useRender({
    render,
    asChild,
    element: "span",
    props: api.getItemGroupLabelProps({ htmlFor }),
    elementProps,
    children,
  });
}

export interface ListboxItemProps
  extends listbox.ListboxItemProps,
    PartProps<"div", listbox.ListboxItemProps> {}

/**
 * A row is identified by its value and nothing else: its position, its neighbours
 * and whether it holds the tab stop are all read back off the DOM by the machine,
 * which is what stops a conditionally rendered row going out of sync with a
 * registry nobody remembered to update.
 */
export function ListboxItem(props: ListboxItemProps): ReactNode {
  const [item, rest] = splitProps(props, ["value", "disabled", "label"]);
  const { render, asChild, children, ...elementProps } = rest;
  const api = ListboxContext.usePart("ListboxItem");

  return (
    <ListboxItemContext.Provider value={item.value}>
      {useRender({
        render,
        asChild,
        element: "div",
        props: api.getItemProps(item),
        elementProps,
        children,
      })}
    </ListboxItemContext.Provider>
  );
}

/** The row's accessible name, and what the typeahead matches on. */
export const ListboxItemText: (props: PartProps<"span">) => ReactNode = createPart(ListboxContext, {
  name: "ListboxItemText",
  element: "span",
  props: (api) => api.getItemTextProps(),
});

/**
 * The checkmark. The state is `aria-selected` on the row, never this glyph — so the
 * node is hidden and the two can never disagree. Give it an inline SVG, never a
 * text glyph: text stands on its font's baseline inside the centred line box, so
 * its ink paints below the box's centre while an SVG's viewBox fills the square.
 */
export function ListboxItemIndicator(props: PartProps<"span">): ReactNode {
  const { render, asChild, children, ...elementProps } = props;
  const api = ListboxContext.usePart("ListboxItemIndicator");
  const value = ListboxItemContext.usePart("ListboxItemIndicator");

  return useRender({
    render,
    asChild,
    element: "span",
    props: api.getItemIndicatorProps({ value }),
    elementProps,
    children,
  });
}
